  if (/^(?:this attack )?does \d+ damage (?:(?:for each)|(?:times the amount of)) (?:basic )?(?:(?:\{[grwlpmdycf]\}|(?:grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy|colorless)) )?energy attached to (?:this pokemon|your opponent's active pokemon|the defending pokemon)(?: and (?:your opponent's active pokemon|the defending pokemon))?\.(?: \(you can.t use more than 1 (?:gx attack|vstar power) in a game\.\))?$/.test(value) || /^this attack does \d+ more damage (?:(?:for each)|(?:times the amount of)) (?:basic )?(?:(?:\{[grwlpmdycf]\}|(?:grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy|colorless)) )?energy attached to (?:this pokemon|your opponent's active pokemon|the defending pokemon)\.(?: \(you can.t use more than 1 (?:gx attack|vstar power) in a game\.\))?$/.test(value)) return 'Supported: the battle format maps attached Energy references to the applicable shared pool; typed checks use its selected Energy type'
  if (/^this attack does \d+ damage for each pokemon in your discard pile\. \(you can.t use more than 1 vstar power in a game\.\)$/.test(value)) return 'Supported: Pokémon discard count; VSTAR once-per-game limit is not tracked'
  if (/\byou can't use more than 1 vstar power in a game\b|\b(?:damage|do \d+ damage) to \d+ of your opponent's benched pokemon\b/.test(value)) return 'Unsupported: once-per-game Power limits or multi-target damage choices are not modeled'
  if (/\bcan't use this attack again as long as .* stays in play\b/.test(value)) return 'Unsupported: whether an attack has already been used while a card remains in play is not tracked'
  if (/\byour opponent can't play (?:any )?(?:trainer|item) cards?\b|\byour opponent can't draw a card at the beginning of .* next turn\b|\buntil the end of your next turn, this pokemon is (?:grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy|dragon|colorless) type\b/.test(value)) return 'Unsupported: turn-long card-play locks or dynamic Pokémon type changes are not modeled'
