  if (/\bdiscard (?:a|an|up to \d+) [a-z0-9' -]+ cards? from your hand\b|\byour opponent may draw \d+ cards?\b/.test(value)) return 'Unsupported: selecting a hand card by its subtype or an opponent-controlled draw prompt is not modeled'
  if (/^this attack does \d+ damage (?:(?:for each)|(?:times the amount of)) (?:basic )?(?:(?:\{[grwlpmdycf]\}|(?:grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy|colorless)) )?energy attached to (?:all of your opponent's pokemon|all of your pokemon|all pokemon)\.(?: \(you can.t use more than 1 (?:gx attack|vstar power) in a game\.\))?$/.test(value) || /^this attack does \d+ more damage for each (?:basic )?(?:(?:\{[grwlpmdycf]\}|(?:grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy|colorless)) )?energy attached to (?:all of your opponent's pokemon|all of your pokemon)\.(?: \(you can.t use more than 1 (?:gx attack|vstar power) in a game\.\))?$/.test(value)) return 'Supported: Energy count from the shared pool; type-specific checks use the selected Energy type, and VSTAR once-per-game limit is not tracked'
  if (/^this attack does \d+ damage (?:(?:for each)|(?:times the amount of)) (?:basic )?(?:(?:\{[grwlpmdycf]\}|(?:grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy|colorless)) )?energy attached to (?:this pokemon|your opponent's active pokemon|the defending pokemon)(?: and (?:your opponent's active pokemon|the defending pokemon))?\.(?: \(you can.t use more than 1 (?:gx attack|vstar power) in a game\.\))?$/.test(value) || /^this attack does \d+ more damage (?:(?:for each)|(?:times the amount of)) (?:basic )?(?:(?:\{[grwlpmdycf]\}|(?:grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy|colorless)) )?energy attached to (?:this pokemon|your opponent's active pokemon|the defending pokemon)\.(?: \(you can.t use more than 1 (?:gx attack|vstar power) in a game\.\))?$/.test(value)) return 'Supported: the battle format maps attached Energy references to the applicable shared pool; typed checks use its selected Energy type'
  if (/^if this pokemon has at least \d+ extra (?:(?:\{[grwlpmdycf]\}|grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy|colorless) )?energy attached(?: to this pokemon)?, this attack does \d+ more damage\.$/.test(value)) return 'Supported: extra Energy threshold uses the shared pool; typed checks use the selected Energy type'
  if (/\b(?:energy attached|energy attached to|energy cards? attached|attach(?:es|ed)? (?:\d+ )?(?:basic )?(?:\{[a-z]+\} )?energy|attach any number of .*energy.* from (?:your )?hand|energy from your discard pile|energy card from|energy cards? (?:there|in (?:your|opponent's) hand)|energy from among your pokemon|discard .*energy.* from (?:(?:your |the )?opponent's? )?(?:active|defending|benched|any|1 of your) pokemon|discard .*energy.* from (?:your )?benched pokemon|discard .*basic .*energy.* from (?:your )?hand|discard .*energy.* from your hand|discard .*energy.* from this pokemon|move .*energy(?: cards?)? from .*pokemon to|all cards attached to (?:them|it|that pokemon))\b/.test(value)) return 'Unsupported: individual Energy attachments or Energy discard zones'
  if (/\breturn (?:a |an |one )?(?:basic )?energy from this pokemon to your hand\b|\battach as many basic energy cards as you like from your hand\b/.test(value)) return 'Unsupported: individual Energy attachments or Energy discard zones'
  if (/^choose 1 of your opponent's pokemon(?:-gx or pokemon-ex)? \d+ times\. \(you can choose the same pokemon more than once\.\) for each time you chose a pokemon, do \d+ damage to it\. this damage isn't affected by weakness or resistance\.(?: \(you can.t use more than 1 (?:gx attack|vstar power) in a game\.\))?$/.test(value)) return 'Supported: repeated selected-target damage with replacement; once-per-game power usage is not tracked'
  if (/\b(?:choose|use) .*attacks? and use it as this attack\b|\bchosen at random \d+ times\b|\bchoose 1 of .* \d+ times\b/.test(value)) return 'Unsupported: dynamic attack copying or repeated target selection'
  if (/^choose \d+ of your opponent's pokemon and put \d+ damage counters? on each of them\.$/.test(value)) return 'Supported: fixed counter placement on a chosen number of distinct opposing Pokémon'
  if (/\bmove as many damage counters on .* to any of .* other pokemon in any way you like\b/.test(value)) return 'Unsupported: flexible damage-counter redistribution'
  if (/\bknock out each of your opponent's pokemon that has \d+ hp or less remaining\b/.test(value)) return 'Unsupported: board-wide Knock Outs with per-target HP thresholds'
  if (value === "knock out your opponent's active pokemon. if your opponent's active pokemon is knocked out in this way, this pokemon does 200 damage to itself.") return 'Supported: Active Pokémon Knock Out with conditional recoil'
  if (/\byour opponent's active pokemon is knocked out in this way\b/.test(value)) return 'Unsupported: effects conditional on a target being Knocked Out'
  if (/\b(?:their|your opponent's) pokemon (?:can't|cannot) attack\b/.test(value)) return 'Unsupported: board-wide attack locks'
  if (/\byour opponent chooses\b|\bhave your opponent (?:switch|choose|discard|select)\b/.test(value)) return 'Unsupported: opponent-controlled choice prompts'
  if (/\b(?:take another turn after this one|at the end of your opponent's next turn|at the end of your opponent's next turn, .* knocked out)\b/.test(value)) return 'Unsupported: extra turns or delayed turn-end effects'
  if (/\bmoved from your bench to the active spot this turn\b|\bwas on the bench and became your active pokemon this turn\b/.test(value)) return 'Unsupported: whether the attacker moved from the Bench this turn is not recorded'
  if (/\b(?:during (?:their|his or her) last turn|attacked last turn|used .* during your last turn|used an attack during (?:his or her|their) last turn|knocked out by damage from an opponent's attack during (?:their|his or her) last turn)\b/.test(value)) return 'Unsupported: required previous-turn history is not recorded'
  if (/\bif an attack does damage to .* during your opponent's next turn.* attacks .* for double that amount\b/.test(value)) return 'Unsupported: attack-triggered retaliation during the opponent turn is not modeled'
  if (/\bopponent puts \d+ markers? onto (?:his or her|their) pokemon\b/.test(value)) return 'Unsupported: opponent-assigned markers and per-Pokémon marker damage are not modeled'
  if (/\b(?:treat any tails flipped .* as if they were heads|whenever .* flips? a coin, treat it as tails)\b/.test(value)) return 'Unsupported: changing later coin-flip results'
  if (/\bduring your opponent's next turn, if this pokemon is damaged by an attack\b.*\bput \d+ damage counters? on the attacking pokemon\b|\bif this pokemon is damaged by an attack \(even if it is knocked out\), put \d+ damage counters? on the attacking pokemon\b/.test(value)) return 'Unsupported: delayed attack-damage retaliation'
  if (/\b(?:your opponent reveals? (?:their|his or her) hand|your opponent discards? .* from their hand|(?:you and your opponent|both players) reveal your hands|put up to \d+ basic pokemon you find there onto your opponent's bench)\b/.test(value)) return 'Unsupported: opponent hand prompts or cross-player hand moves'
  if (/\b(?:discard any number of your benched pokemon|discard your other benched pokemon)\b/.test(value)) return 'Unsupported: selecting and discarding Pokémon from the Bench'
  if (/\buntil this pokemon leaves play, it gains an ability\b|\bweakness of each of your opponent's pokemon in play is now\b/.test(value)) return 'Unsupported: persistent dynamic Ability or Weakness changes'
  if (/\b(?:search your deck|look at the top card of your deck|shuffl(?:e|es) (?!your hand into your deck).* into (?:your|their|his or her) deck|top \d+ cards|bottom \d+ cards|discard the top|from your discard pile|devolve|evolve this pokemon|put .* onto your bench|put any number of your pokemon in play .* into your hand)\b/.test(value)) return 'Unsupported: deck, discard, or evolution card operations'
  if (/\bduring your opponent's next turn, the attack cost of each of the defending pokemon's attacks is (?:\{c\}|colorless) more\b/.test(value)) return 'Unsupported: temporary attack-cost increases on an opposing Pokémon are not represented in battle state'
  if (/\bask your opponent if you may\b|\byour opponent may choose\b|\beither way, you may do the same\b/.test(value)) return 'Unsupported: attacks that wait for an opponent response before choosing a resolution are not modeled'
  if (/\b(?:each defending pokemon|each of your opponent's defending pokemon)\b/.test(value)) return 'Unsupported: the battle format has one Active Pokémon per side and does not support multiple Defending Pokémon'
  if (/\b(?:attack|attacks) from (?:this pokemon's )?(?:previous evolutions|previous evolution)\b|\bfrom (?:this pokemon's )?(?:basic pokemon card|stage 1 evolution card|evolution card)\b/.test(value)) return 'Unsupported: Pokémon Evolution stack attack history is not stored in battle state'
  if (/\b(?:look at|reveal) (?:your opponent's )?hand\b|\bguess(?:es|ed)? (?:if|the type of)\b/.test(value) && /\b(?:draw|choose|put|return|discard|guess)\b/.test(value)) return 'Unsupported: private hand reveal and opponent guessing interactions are not modeled'
  if (/\b(?:flip a coin\. )?if heads,? (?:each player|each player who gets heads)\b.*\bremove\b.*\bdamage counters?\b/.test(value) || /\beach player flips a coin\b.*\bchooses? a total of \d+ damage counters?\b/.test(value)) return 'Unsupported: simultaneous player-controlled damage-counter healing choices are not represented'
  if (/\bsearch your discard pile for .* basic energy card\b|\bsearch your discard pile for .*basic energy cards?\b/.test(value)) return 'Unsupported: Energy card identities in the discard pile are not modeled'
  if (/\b(?:search|choose) (?:either player's|your opponent's) discard pile\b|\bdiscard pile\b.*\b(?:put .* on top of|put .* into|attach .* from)\b/.test(value)) return 'Unsupported: card identities in both players’ discard piles and their movement are not modeled'
  if (/\b(?:use|choose|copy) (?:any |1 of |an? )?attack from\b|\battacks? copies? (?:the|an?) attack\b|\bperform(?:s)? that attack\b/.test(value)) return 'Unsupported: choosing and resolving a different Pokémon’s attack at runtime is not modeled'
  if (/\b(?:previous evolutions|previous evolution)\b/.test(value)) return 'Unsupported: attacks on earlier Evolution cards are not retained in battle state'
  if (/\bdiscard(?:s|ed)? the top card of (?:each player's|his or her|their|your|the) deck\b|\bdiscard cards? from the top of your deck\b|\bdiscard up to \d+ cards? from the top of your deck\b/.test(value)) return 'Unsupported: deck contents and choosing or counting discarded deck cards are not modeled'
  if (/\b(?:trainer|supporter|item|moo ?moo milk|sweet honey|fossil) cards?\b/.test(value) && /\b(?:hand|discard pile|attached|discard)\b/.test(value)) return 'Unsupported: Trainer card identities and attachments are not represented in battle state'
  if (/\benergy (?:cards? )?(?:attached to|attached|from this pokemon|in (?:your|your opponent's) discard pile)\b|\b(?:basic|water|lightning) energy attached\b/.test(value)) return 'Unsupported: individual Energy attachments and Energy card identities in discard piles are not represented'
  if (/\b(?:each|both) players? (?:discard|put|search)\b.*\b(?:deck|discard pile|bench)\b/.test(value)) return 'Unsupported: paired player choices across hidden card zones are not represented'
